"""Independent brute-force reference implementation of PROTOCOL.md (slow, exact)."""
import itertools


def term_value(term, cells, names, nf):
    if 'const' in term:
        return term['const']
    if 'sum' in term:
        return sum(cells[ref[0] * nf + names[ref[1]]] for ref in term['sum'])
    if 'scale' in term:
        return term['scale'] * cells[term['ref'][0] * nf + names[term['ref'][1]]]
    return cells[term['ref'][0] * nf + names[term['ref'][1]]]


def cmp_value(left, op, right):
    return {'eq': left == right, 'ne': left != right, 'lt': left < right,
            'le': left <= right, 'gt': left > right, 'ge': left >= right}[op]


def pred_value(pred, cells, names, nf, slots):
    if pred['kind'] == 'cmp':
        return cmp_value(term_value(pred['left'], cells, names, nf), pred['op'],
                         term_value(pred['right'], cells, names, nf))
    index = names[pred['field']]
    results = [cmp_value(cells[slot * nf + index], pred['op'], pred['value']) for slot in range(slots)]
    return any(results) if pred['kind'] == 'any' else all(results)


def job_tables(job):
    fields = job['fields']
    names = {f['name']: i for i, f in enumerate(fields)}
    nf = len(fields)
    slots = job['slots']
    domains = [list(f['domain']) for _ in range(slots) for f in fields]
    cells = nf * slots
    windows = [list(itertools.chain.from_iterable(w)) for w in job['train']]
    universe = [[domains[c][positions[c]] for c in range(cells)]
                for positions in itertools.product(*[range(len(d)) for d in domains])]
    evaluate = lambda rows: [[pred_value(p, row, names, nf, slots) for p in job['predicates']]
                             for row in rows]
    return names, nf, slots, cells, windows, universe, evaluate(windows), evaluate(universe)


def solve(job):
    names, nf, slots, cells, windows, universe, ttab, utab = job_tables(job)
    count_train = len(windows)
    P = len(job['predicates'])
    rules = []
    for size in range(1, min(job['width'], P) + 1):
        for clause in itertools.combinations(range(P), size):
            if not all(any(ttab[i][p] for p in clause) for i in range(count_train)):
                continue
            witnesses = []
            minimal = True
            for p in clause:
                rest = tuple(q for q in clause if q != p)
                hit = [i for i in range(count_train) if not any(ttab[i][q] for q in rest)]
                if not hit:
                    minimal = False
                    break
                witnesses.append(next(i for i in hit if ttab[i][p]))
            if not minimal:
                continue
            counter = next((u for u in range(len(universe)) if not any(utab[u][p] for p in clause)), None)
            if counter is None:
                continue
            rules.append({'clause': list(clause), 'witnesses': witnesses, 'counterexample': counter})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))
    approved = {tuple(c) for c in job['approved']}
    active = [r['clause'] for r in rules if tuple(r['clause']) in approved]

    def feasible(query):
        fixed = [(b['ref'][0] * nf + names[b['ref'][1]], b['value']) for b in query['fixed']]
        out = []
        for u in range(len(universe)):
            if not all(any(utab[u][p] for p in clause) for clause in active):
                continue
            if any(universe[u][c] != v for c, v in fixed):
                continue
            out.append(u)
        return out

    answers = []
    for query in job['queries']:
        tcell = query['target'][0] * nf + names[query['target'][1]]
        prefix = query['prefix']
        base = feasible(query)
        spell = {u: str(universe[u][tcell]) for u in base}
        completions = [u for u in base if spell[u].startswith(prefix)]
        if not completions:
            answers.append({'count': 0, 'tokens': [], 'witness': None})
            continue
        tokens = [d for d in '0123456789' if any(spell[u].startswith(prefix + d) for u in base)]
        if prefix and (prefix == '0' or prefix[0] != '0') and any(spell[u] == prefix for u in base):
            tokens.append('END')
        answers.append({'count': len(completions), 'tokens': tokens, 'witness': min(completions)})
    return {'rules': rules, 'active': active, 'answers': answers}


def solve_batch(batch):
    return {'results': [solve(job) for job in batch['jobs']]}
