"""Random job generator for differential testing against the reference."""
import random


def gen_job(rng, big=False):
    nf = rng.randint(1, 3 if big else 2)
    slots = rng.randint(1, 2 if not big else 3)
    types = ['time', 'size', 'count', 'id', 'flag']
    fields = []
    for i in range(nf):
        t = types[rng.randrange(len(types))]
        if t in ('id', 'flag'):
            size = rng.randint(1, 4)
            domain = sorted(rng.sample(range(0, 20), size))
        else:
            size = rng.randint(1, 5)
            domain = sorted(rng.sample(range(0, 40), size))
        fields.append({'name': 'f%d' % i, 'type': t, 'domain': domain})
    numeric = [f for f in fields if f['type'] in ('time', 'size', 'count')]
    preds = []
    kinds = ['cmp', 'any', 'all']
    ops = ['eq', 'ne', 'lt', 'le', 'gt', 'ge']
    n_pred = rng.randint(1, 6 if not big else 10)
    for _ in range(n_pred):
        kind = kinds[rng.randrange(3)]
        if kind == 'cmp':
            # left term
            side = rng.random()
            if numeric and side < 0.34:
                f = rng.choice(numeric)
                left = {'ref': [rng.randrange(slots), f['name']]}
                op = rng.choice(ops)
            elif numeric and side < 0.6:
                f = rng.choice(numeric)
                left = {'scale': rng.randint(0, 5), 'ref': [rng.randrange(slots), f['name']]}
                op = rng.choice(ops)
            elif numeric:
                picks = [(s, g['name']) for s in range(slots) for g in [rng.choice(numeric)]]
                picks = list({(s, f['name']) for s in range(slots) for f in numeric})
                rng.shuffle(picks)
                left = {'sum': picks[:rng.randint(1, min(slots, len(picks)))]}
                op = rng.choice(ops)
            else:
                f = fields[rng.randrange(nf)]
                left = {'ref': [rng.randrange(slots), f['name']]}
                op = rng.choice(['eq', 'ne'])
            ftype = None
            # find type of left for the constant
            def reftype(term_):
                if 'ref' in term_:
                    return next(f['type'] for f in fields if f['name'] == term_['ref'][1])
                if 'scale' in term_:
                    return next(f['type'] for f in fields if f['name'] == term_['ref'][1])
                if 'sum' in term_:
                    return next(f['type'] for f in fields if f['name'] == term_['sum'][0][1])
                return term_['type']
            ftype = reftype(left)
            right = {'const': rng.randint(0, 20), 'type': ftype}
            preds.append({'kind': 'cmp', 'left': left, 'op': op, 'right': right})
        else:
            f = fields[rng.randrange(nf)]
            op = rng.choice(ops if f['type'] in ('time', 'size', 'count') else ['eq', 'ne'])
            preds.append({'kind': kind, 'field': f['name'], 'op': op, 'value': rng.randint(0, 20)})
    n_train = rng.randint(1, 6)
    train = [[[rng.choice(f['domain']) for f in fields] for _ in range(slots)] for _ in range(n_train)]
    # ensure train rows are windows of lists of rows
    width = rng.randint(1, 3)
    all_clauses = []
    for size in range(1, width + 1):
        for clause in [tuple(sorted(rng.sample(range(len(preds)), size)))]:
            all_clauses.append(list(clause))
    approved = random.sample(all_clauses, min(len(all_clauses), rng.randint(0, 6)))
    queries = []
    for _ in range(rng.randint(0, 5)):
        target = [rng.randrange(slots), rng.choice(fields)['name']]
        fixed = []
        used = set()
        for _ in range(rng.randint(0, min(3, slots * nf - 1))):
            cell = (rng.randrange(slots), rng.choice(fields)['name'])
            if tuple(cell) == tuple(target) or cell in used:
                continue
            used.add(cell)
            domain = next(f['domain'] for f in fields if f['name'] == cell[1])
            fixed.append({'ref': [cell[0], cell[1]], 'value': rng.choice(domain)})
        prefix = rng.choice(['', '', '0', '1', '2', '10', '01', '3', '1234567'])[:rng.randint(0, 3)]
        queries.append({'fixed': fixed, 'target': target, 'prefix': prefix})
    return {'fields': fields, 'slots': slots, 'predicates': preds, 'width': width,
            'train': train, 'approved': approved, 'queries': queries}
